const { collect } = require('../src/collect');

describe('collect', () => {
  test('returns exactly target unique items', async () => {
    let call = 0;
    const findCandidates = () => {
      call++;
      return [call * 10, call * 10 + 1, call * 10 + 2];
    };
    const result = await collect(5, findCandidates);
    expect(result).toHaveLength(5);
    expect(new Set(result).size).toBe(5);
  });

  test('deduplicates overlapping results across rounds', async () => {
    let call = 0;
    const findCandidates = () => {
      call++;
      if (call === 1) return ['a', 'b', 'c'];
      if (call === 2) return ['b', 'c', 'd']; // b, c are duplicates
      return ['e', 'f'];
    };
    const result = await collect(5, findCandidates);
    expect(result).toHaveLength(5);
    expect(new Set(result).size).toBe(5);
  });

  test('logs new items added per round', async () => {
    const logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    let call = 0;
    const findCandidates = () => {
      call++;
      return [`item${call}`];
    };
    await collect(3, findCandidates);
    expect(logSpy).toHaveBeenCalledTimes(3);
    expect(logSpy).toHaveBeenNthCalledWith(1, 'Round added 1 new items (total unique: 1)');
    expect(logSpy).toHaveBeenNthCalledWith(2, 'Round added 1 new items (total unique: 2)');
    expect(logSpy).toHaveBeenNthCalledWith(3, 'Round added 1 new items (total unique: 3)');
    logSpy.mockRestore();
  });

  test('logs 0 new items when a round returns only duplicates', async () => {
    const logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    let call = 0;
    const findCandidates = () => {
      call++;
      if (call === 1) return [1, 2];
      if (call === 2) return [1, 2]; // all duplicates
      return [3, 4, 5];
    };
    await collect(4, findCandidates);
    expect(logSpy).toHaveBeenNthCalledWith(2, 'Round added 0 new items (total unique: 2)');
    logSpy.mockRestore();
  });

  test('works with async findCandidates', async () => {
    let call = 0;
    const findCandidates = async () => {
      call++;
      return [call];
    };
    const result = await collect(3, findCandidates);
    expect(result).toHaveLength(3);
  });
});
