- [ ] **Step 3: Implement `collect()`**

Overwrite `src/collect.js` with:
```javascript
async function collect(target, findCandidates) {
  const seen = new Set();

  while (seen.size < target) {
    const candidates = await findCandidates();
    const before = seen.size;
    for (const item of candidates) {
      seen.add(item);
    }
    const added = seen.size - before;
    console.log(`Round added ${added} new items (total unique: ${seen.size})`);
  }

  return Array.from(seen).slice(0, target);
}

module.exports = { collect };
```

